#!/usr/bin/env bash
set -euo pipefail; SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"; python3 -m pip install --user -r "$SCRIPT_DIR/requirements.txt"; mkdir -p "$HOME/.claw-worker" "$HOME/.local/bin" "$HOME/.config/systemd/user"; python3 -c 'from pathlib import Path; import secrets; p = Path.home() / ".claw-worker" / "token"; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(secrets.token_hex(16), encoding="utf-8") if not p.exists() else None'; install -m 0755 "$SCRIPT_DIR/claw_worker.py" "$HOME/.local/bin/claw_worker.py"; printf '%s\n' '[Unit]' 'Description=Claw Worker daemon' 'After=network.target' '' '[Service]' 'Type=simple' 'WorkingDirectory=%h/workspace' 'Environment=CLAW_WORKER_WORKSPACE=%h/workspace' 'ExecStart=%h/.local/bin/claw_worker.py' 'Restart=always' 'RestartSec=5' '' '[Install]' 'WantedBy=default.target' > "$HOME/.config/systemd/user/claw-worker.service"; systemctl --user daemon-reload; systemctl --user enable --now claw-worker.service
